//! The Tiger's internal components as layered targets: the measured CAD envelopes
//! (`catalog/tiger_cad_component_voxels.v1.json`, generated by `tools/tiger_cad_voxelize.py` from the
//! owner's RM-5010 kit CAD registered to the game's hull frame) plus an authored casing and a
//! homogenised interior for each. See docs/FEA_DAMAGE_MODEL_20261102.md, "Geometry".
//!
//! Named approximations:
//! * Envelope: the CAD solids voxelised at 20 mm. A voxel boundary lies within half a cell diagonal
//!   (17.3 mm) of the true surface; the catalog records each component's voxel volume against the
//!   exact solid volume (0.94–1.06).
//! * Casing: authored material and thickness (the kit CAD is solid plastic; its walls are not the
//!   real casing). Interior: the component's estimated real mass spread over its real volume.
//! * Scale: the game's Tiger is the kit at 1.112 × 1:35 (about 11 % larger than the real vehicle),
//!   so interior density is divided by that ratio: the mass a straight path meets equals the real
//!   component's. Casing thickness is not scaled.

use glam::{Mat4, Vec3};
use serde::Serialize;
use std::sync::OnceLock;

use super::materials::MaterialId;

/// Game length over real length: the baked Tiger is the kit CAD at 0.038919827 m per kit mm
/// against the kit's nominal 1:35 (0.035 m per mm). docs/research/TIGER_CAD_COMPONENTS_20261102.md.
pub const GAME_OVER_REAL_LENGTH: f32 = 0.038_919_827 / 0.035;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, serde::Deserialize)]
pub enum Side {
    Left,
    Right,
}

/// The vehicle system a component belongs to. The game maps these onto its modules.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, serde::Deserialize)]
pub enum System {
    Engine,
    AirFilters,
    Cooling(Side),
    Fuel(Side),
    Gearbox,
    Steering,
    FinalDrive(Side),
    Ammunition,
    Radio,
    HullMg,
    MainGun,
    CoaxMg,
    GunnerSight,
    TurretTraverse,
    Seat,
}

impl System {
    pub fn name(self) -> &'static str {
        match self {
            System::Engine => "engine",
            System::AirFilters => "air filters",
            System::Cooling(Side::Left) => "left radiator and fans",
            System::Cooling(Side::Right) => "right radiator and fans",
            System::Fuel(Side::Left) => "left fuel tank",
            System::Fuel(Side::Right) => "right fuel tank",
            System::Gearbox => "gearbox",
            System::Steering => "steering unit",
            System::FinalDrive(Side::Left) => "left final drive",
            System::FinalDrive(Side::Right) => "right final drive",
            System::Ammunition => "ammunition stowage",
            System::Radio => "radio",
            System::HullMg => "hull MG",
            System::MainGun => "main gun",
            System::CoaxMg => "coaxial MG",
            System::GunnerSight => "gunner's sight",
            System::TurretTraverse => "turret traverse",
            System::Seat => "seat",
        }
    }
}

/// What fills a component behind its casing.
#[derive(Clone, Copy, Debug, Serialize)]
pub enum Interior {
    /// Machinery homogenised to its mean density: `real_mass_kg` over the component's real volume,
    /// resisting like `matrix` per unit areal density.
    Homogenised { matrix: MaterialId, real_mass_kg: f32 },
    /// A tank of `liquid` filled to the live fill fraction, vapour (air) above.
    Tank { liquid: MaterialId },
    /// Nothing that resists a shell (air, cushions); live rounds in a bin come from the game's
    /// live-ammunition records instead.
    Empty,
}

#[derive(Clone, Copy, Debug, Serialize)]
pub struct ComponentSpec {
    pub id: &'static str,
    pub name: &'static str,
    pub system: System,
    pub casing: MaterialId,
    pub casing_mm: f32,
    pub interior: Interior,
    pub provenance: &'static str,
}

use Interior::{Empty, Homogenised, Tank};
