#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub enum Frame {
    Hull,
    Turret,
    /// Turret-local, but elevating with the gun about the trunnion's X axis.
    Gun,
}

/// One component's occupancy grid in its own frame.
#[derive(Clone, Debug)]
pub struct VoxelEnvelope {
    pub spec: usize,
    pub frame: Frame,
    pub origin: Vec3,
    pub cell: f32,
    pub dims: [usize; 3],
    bits: Vec<u64>,
    pub occupied_cells: usize,
    pub voxel_volume_m3: f32,
    pub solid_volume_m3: f32,
    /// Trunnion point (turret-local) for `Frame::Gun`.
    pub trunnion: Vec3,
}

impl VoxelEnvelope {
    #[inline]
    fn index(&self, ix: usize, iy: usize, iz: usize) -> usize {
        (ix * self.dims[2] + iz) * self.dims[1] + iy
    }
    #[inline]
    pub fn occupied(&self, ix: i64, iy: i64, iz: i64) -> bool {
        if ix < 0 || iy < 0 || iz < 0 {
            return false;
        }
        let (ix, iy, iz) = (ix as usize, iy as usize, iz as usize);
        if ix >= self.dims[0] || iy >= self.dims[1] || iz >= self.dims[2] {
            return false;
        }
        let i = self.index(ix, iy, iz);
        self.bits[i >> 6] >> (i & 63) & 1 == 1
    }
    pub fn cell_of(&self, p: Vec3) -> [i64; 3] {
        let q = (p - self.origin) / self.cell;
        [q.x.floor() as i64, q.y.floor() as i64, q.z.floor() as i64]
    }
    pub fn contains(&self, p: Vec3) -> bool {
        let c = self.cell_of(p);
        self.occupied(c[0], c[1], c[2])
    }
    pub fn bounds(&self) -> (Vec3, Vec3) {
        let size = Vec3::new(self.dims[0] as f32, self.dims[1] as f32, self.dims[2] as f32) * self.cell;
        (self.origin, self.origin + size)
    }
    /// Outward normal at a boundary point from the occupancy gradient over the 3×3×3 cells around
    /// it (a staircase estimate; its error against the true surface is reported by the tests).
    pub fn normal_at(&self, p: Vec3) -> Vec3 {
        let c = self.cell_of(p);
        let mut g = Vec3::ZERO;
        for dx in -1..=1i64 {
            for dy in -1..=1i64 {
                for dz in -1..=1i64 {
                    if (dx, dy, dz) == (0, 0, 0) {
                        continue;
                    }
                    if self.occupied(c[0] + dx, c[1] + dy, c[2] + dz) {
                        let d = Vec3::new(dx as f32, dy as f32, dz as f32);
                        g -= d / d.length_squared();
                    }
                }
            }
        }
        g.normalize_or_zero()
    }
    /// Maximal occupied runs of the segment `a → b`, as path parameters in [0, 1] (entry, exit),
    /// by a 3-D DDA through the grid (Amanatides & Woo 1987). Entry and exit lie on cell faces.
    pub fn segment_runs(&self, a: Vec3, b: Vec3) -> Vec<(f32, f32)> {
        let mut runs = Vec::new();
        let d = b - a;
        let (lo, hi) = self.bounds();
        // Clip to the grid's box.
        let mut t0 = 0.0f32;
        let mut t1 = 1.0f32;
        for k in 0..3 {
            if d[k].abs() < 1e-12 {
                if a[k] < lo[k] || a[k] > hi[k] {
                    return runs;
                }
            } else {
                let inv = 1.0 / d[k];
                let mut ta = (lo[k] - a[k]) * inv;
                let mut tb = (hi[k] - a[k]) * inv;
                if ta > tb {
                    std::mem::swap(&mut ta, &mut tb);
                }
                t0 = t0.max(ta);
                t1 = t1.min(tb);
            }
        }
        if t0 >= t1 {
            return runs;
        }
        let eps = 1e-6;
        let start = a + d * (t0 + eps).min(t1);
        let mut cell = self.cell_of(start);
        for k in 0..3 {
            cell[k] = cell[k].clamp(0, self.dims[k] as i64 - 1);
        }
        let step: [i64; 3] = [0, 1, 2].map(|k| if d[k] > 0.0 { 1 } else if d[k] < 0.0 { -1 } else { 0 });
        let mut t_max = [f32::INFINITY; 3];
        let mut t_delta = [f32::INFINITY; 3];
        for k in 0..3 {
            if step[k] != 0 {
                let boundary = self.origin[k] + (cell[k] + if step[k] > 0 { 1 } else { 0 }) as f32 * self.cell;
                t_max[k] = (boundary - a[k]) / d[k];
                t_delta[k] = self.cell / d[k].abs();
            }
        }
        let mut t = t0;
        let mut open: Option<f32> = None;
        loop {
            let inside = self.occupied(cell[0], cell[1], cell[2]);
            match (inside, open) {
                (true, None) => open = Some(t),
                (false, Some(start)) => {
                    runs.push((start, t));
                    open = None;
                }
                _ => {}
            }
            let k = if t_max[0] < t_max[1] {
                if t_max[0] < t_max[2] { 0 } else { 2 }
            } else if t_max[1] < t_max[2] {
                1
            } else {
                2
            };
            if t_max[k] > t1 || step[k] == 0 {
                break;
            }
            t = t_max[k];
            cell[k] += step[k];
            t_max[k] += t_delta[k];
            if cell[k] < 0 || cell[k] >= self.dims[k] as i64 {
                break;
            }
        }
        if let Some(start) = open {
            runs.push((start, t1));
        }
        runs
    }
}

/// The parsed component set.
#[derive(Debug)]
pub struct ComponentSet {
    pub envelopes: Vec<VoxelEnvelope>,
    pub cell_m: f32,
    pub surface_bound_m: f32,
}

static VOXELS_JSON: &str = include_str!("../../catalog/tiger_cad_component_voxels.v1.json");

pub fn tiger_components() -> &'static ComponentSet {
    static SET: OnceLock<ComponentSet> = OnceLock::new();
    SET.get_or_init(|| parse_voxels(VOXELS_JSON).expect("committed component voxel catalog parses"))
}

fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let mut out = Vec::with_capacity(s.len() * 3 / 4);
    let mut acc = 0u32;
    let mut bits = 0u32;
    for c in s.bytes() {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => continue,
            b'\n' | b'\r' | b' ' => continue,
            _ => return None,
        } as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
            acc &= (1 << bits) - 1;
        }
    }
    Some(out)
}

fn parse_voxels(text: &str) -> Option<ComponentSet> {
    let root: serde_json::Value = serde_json::from_str(text).ok()?;
    let cell = root.get("cell_m")?.as_f64()? as f32;
    let surface_bound = root.get("surface_bound_m")?.as_f64()? as f32;
    let trunnion = root.get("frames")?.get("gun_trunnion_turret_m")?.as_array()?;
    let trunnion = Vec3::new(
        trunnion.first()?.as_f64()? as f32,
        trunnion.get(1)?.as_f64()? as f32,
        trunnion.get(2)?.as_f64()? as f32,
    );
    let mut envelopes = Vec::new();
    for c in root.get("components")?.as_array()? {
        let id = c.get("id")?.as_str()?;
        let spec = COMPONENT_SPECS.iter().position(|s| s.id == id)?;
        let frame = match (c.get("frame")?.as_str()?, c.get("elevates_with_gun").is_some()) {
            ("hull", _) => Frame::Hull,
            ("turret", true) => Frame::Gun,
            ("turret", false) => Frame::Turret,
            _ => return None,
        };
        let o = c.get("origin_m")?.as_array()?;
        let origin = Vec3::new(o.first()?.as_f64()? as f32, o.get(1)?.as_f64()? as f32, o.get(2)?.as_f64()? as f32);
        let d = c.get("dims")?.as_array()?;
        let dims = [d.first()?.as_u64()? as usize, d.get(1)?.as_u64()? as usize, d.get(2)?.as_u64()? as usize];
        let total = dims[0] * dims[1] * dims[2];
        let bytes = base64_decode(c.get("rle_b64")?.as_str()?)?;
        let mut bits = vec![0u64; total.div_ceil(64)];
        let mut pos = 0usize;
        let mut full = false;
        let mut i = 0usize;
        let mut occupied = 0usize;
        while i < bytes.len() {
            let mut run = 0usize;
            let mut shift = 0;
            loop {
                let b = *bytes.get(i)?;
                i += 1;
                run |= ((b & 0x7f) as usize) << shift;
                shift += 7;
                if b & 0x80 == 0 {
                    break;
                }
            }
            if full {
                for k in pos..(pos + run).min(total) {
                    bits[k >> 6] |= 1 << (k & 63);
                }
                occupied += run;
            }
            pos += run;
            full = !full;
        }
        if pos != total {
            return None;
        }
        envelopes.push(VoxelEnvelope {
            spec,
            frame,
            origin,
            cell,
            dims,
            bits,
            occupied_cells: occupied,
            voxel_volume_m3: c.get("voxel_volume_m3")?.as_f64()? as f32,
            solid_volume_m3: c.get("solid_volume_m3")?.as_f64()? as f32,
            trunnion,
        });
    }
    Some(ComponentSet { envelopes, cell_m: cell, surface_bound_m: surface_bound })
}

/// Where the turret and gun stand, for placing turret-frame components in the hull frame.
#[derive(Clone, Copy, Debug)]
pub struct Articulation {
    /// Hull-local → turret-local.
    pub hull_to_turret: Mat4,
    /// Gun elevation, radians, positive raises the muzzle.
    pub gun_elevation: f32,
}

impl Articulation {
    /// Turret forward, gun level: the CAD's own pose.
    pub fn rest(turret_pivot: Vec3) -> Self {
        Self { hull_to_turret: Mat4::from_translation(-turret_pivot), gun_elevation: 0.0 }
    }
    /// Hull-local point → the component's own frame.
    pub fn to_component(&self, env: &VoxelEnvelope, p: Vec3) -> Vec3 {
        match env.frame {
            Frame::Hull => p,
            Frame::Turret => self.hull_to_turret.transform_point3(p),
            Frame::Gun => {
                let q = self.hull_to_turret.transform_point3(p);
                // Undo the elevation: rotate about the trunnion's X axis. Raising the muzzle (+Z
                // forward) up (+Y) is a rotation of -elevation about +X in this frame.
                let r = Mat4::from_rotation_x(self.gun_elevation);
                env.trunnion + r.transform_vector3(q - env.trunnion)
            }
        }
    }
    /// A hull-local direction into the component's frame.
    pub fn to_component_dir(&self, env: &VoxelEnvelope, d: Vec3) -> Vec3 {
        match env.frame {
            Frame::Hull => d,
            Frame::Turret => self.hull_to_turret.transform_vector3(d),
            Frame::Gun => Mat4::from_rotation_x(self.gun_elevation).transform_vector3(self.hull_to_turret.transform_vector3(d)),
        }
    }
    /// A direction in the component's frame back to the hull frame.
    pub fn dir_to_hull(&self, env: &VoxelEnvelope, d: Vec3) -> Vec3 {
        let inv = self.hull_to_turret.inverse();
        match env.frame {
            Frame::Hull => d,
            Frame::Turret => inv.transform_vector3(d),
            Frame::Gun => inv.transform_vector3(Mat4::from_rotation_x(-self.gun_elevation).transform_vector3(d)),
        }
    }
}

/// Real volume of a component (m³) from its game-scale voxel volume.
pub fn real_volume_m3(env: &VoxelEnvelope) -> f32 {
    env.voxel_volume_m3 / GAME_OVER_REAL_LENGTH.powi(3)
}

/// Density to use along a game-scale path through a homogenised interior so the areal density met
/// equals the real component's.
pub fn path_density(env: &VoxelEnvelope, real_mass_kg: f32) -> f32 {
    real_mass_kg / real_volume_m3(env).max(1e-6) / GAME_OVER_REAL_LENGTH
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_catalog_component_has_a_spec_and_decodes_to_its_counted_cells() {
        let set = tiger_components();
        assert_eq!(set.envelopes.len(), COMPONENT_SPECS.len());
        for env in &set.envelopes {
            let mut n = 0usize;
            for ix in 0..env.dims[0] as i64 {
                for iy in 0..env.dims[1] as i64 {
                    for iz in 0..env.dims[2] as i64 {
                        n += env.occupied(ix, iy, iz) as usize;
                    }
                }
            }
            assert_eq!(n, env.occupied_cells, "{}", COMPONENT_SPECS[env.spec].id);
            let ratio = env.voxel_volume_m3 / env.solid_volume_m3;
            assert!((0.9..1.1).contains(&ratio), "{} voxel/solid volume {ratio}", COMPONENT_SPECS[env.spec].id);
        }
    }

    #[test]
    fn segment_runs_agree_with_point_sampling() {
        let set = tiger_components();
        let engine = set.envelopes.iter().find(|e| COMPONENT_SPECS[e.spec].id == "engine_block").unwrap();
        let (lo, hi) = engine.bounds();
        let mid = (lo + hi) * 0.5;
        for (a, b) in [
            (Vec3::new(lo.x - 0.3, mid.y, mid.z), Vec3::new(hi.x + 0.3, mid.y, mid.z)),
            (Vec3::new(mid.x, hi.y + 0.4, mid.z + 0.1), Vec3::new(mid.x - 0.2, lo.y - 0.2, mid.z - 0.3)),
            (Vec3::new(lo.x - 0.1, lo.y + 0.2, hi.z + 0.5), Vec3::new(hi.x + 0.2, hi.y - 0.1, lo.z - 0.4)),
        ] {
            let runs = engine.segment_runs(a, b);
            assert!(!runs.is_empty(), "a line through the engine's middle must cross it");
            // Sample the segment finely; every sample inside the solid lies in a run and vice versa,
            // except within one cell of a run boundary (the DDA reports cell faces).
            let len = (b - a).length();
            let tol = engine.cell * 1.8 / len;
            for i in 0..2000 {
                let t = (i as f32 + 0.5) / 2000.0;
                let inside = engine.contains(a + (b - a) * t);
                let in_run = runs.iter().any(|&(s, e)| t >= s && t <= e);
                let near_edge = runs.iter().any(|&(s, e)| (t - s).abs() < tol || (t - e).abs() < tol);
                assert!(inside == in_run || near_edge, "t={t} inside={inside} in_run={in_run}");
            }
        }
    }

    #[test]
    fn components_sit_where_the_hull_puts_them() {
        let set = tiger_components();
        let centre = |id: &str| {
            let e = set.envelopes.iter().find(|e| COMPONENT_SPECS[e.spec].id == id).unwrap();
            let (lo, hi) = e.bounds();
            (lo + hi) * 0.5
        };
        // Engine aft, gearbox forward, fuel tanks either side of the engine (+X is left).
        assert!(centre("engine_block").z < -1.0);
        assert!(centre("gearbox").z > 1.0);
        assert!(centre("fuel_tank_left").x > 0.5 && centre("fuel_tank_right").x < -0.5);
        assert!(centre("final_drive_left").x > 1.0 && centre("final_drive_left").z > 2.5);
    }

    #[test]
    fn interior_density_preserves_real_areal_density() {
        let set = tiger_components();
        let e = set.envelopes.iter().find(|e| COMPONENT_SPECS[e.spec].id == "engine_block").unwrap();
        let rho = path_density(e, 1050.0);
        // Mass met along a game path = rho * L_game; the real path is L_game / ratio through the
        // real volume, whose mean density is m / V_real.
        let real_rho = 1050.0 / real_volume_m3(e);
        let l_game = 1.0;
        assert!((rho * l_game - real_rho * l_game / GAME_OVER_REAL_LENGTH).abs() < 1e-3);
        assert!(rho > 500.0 && rho < 4000.0, "engine path density {rho}");
    }

    #[test]
    fn gun_frame_rotation_round_trips() {
        let set = tiger_components();
        let breech = set.envelopes.iter().find(|e| e.frame == Frame::Gun).unwrap();
        let mut art = Articulation::rest(Vec3::new(0.0, 0.524, 0.019));
        art.gun_elevation = 0.15;
        // The trunnion itself does not move when the gun elevates.
        let trunnion_hull = breech.trunnion + Vec3::new(0.0, 0.524, 0.019);
        assert!((art.to_component(breech, trunnion_hull) - breech.trunnion).length() < 1e-5);
        // Elevating the muzzle lowers the breech: a hull point below the trunnion and behind it
        // maps to a point nearer the gun's own axis than it is in the turret frame.
        let d = Vec3::new(0.0, 0.2, 0.9).normalize();
        let back = art.dir_to_hull(breech, art.to_component_dir(breech, d));
        assert!((back - d).length() < 1e-5);
        // The game's gun_model is turret * T(trunnion) * Rx(-pitch): a muzzle-forward gun direction
        // (+Z) at +pitch points up in the hull frame.
        let muzzle = art.dir_to_hull(breech, Vec3::Z);
        assert!(muzzle.y > 0.1, "{muzzle:?}");
    }
}
